using System.Text.Json;
using System.Text.Json.Serialization;

namespace PoeRegex.Core.Compilation;

/// <summary>
/// Precomputed exact fragments for the PoE2 catalog, one map for global
/// searches and one per item class. The table is generated by the exact
/// solver at data time; runtime is lookup-only.
/// </summary>
public sealed class FragmentTable
{
    public string Game { get; init; } = "";
    public string DataVersion { get; init; } = "";

    /// <summary>
    /// The display basis the fragments were proven against. The current basis
    /// is the advanced item-search text, where ranged stats show
    /// <c>roll(min-max)</c>. An empty value is treated as the legacy table
    /// that predates this field.
    /// </summary>
    public string TargetModel { get; init; } = "";

    public const string AdvancedRanges = "advanced-ranges-v1";
    public Dictionary<string, string> Global { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, Dictionary<string, string>> ByClass { get; init; } = new(StringComparer.Ordinal);

    /// <summary>
    /// Precomputed shortest class-line selectors. Values are regex fragments
    /// and may contain wildcards; paste/compiler class anchors must not rebuild
    /// the vendor-derived class corpus on the browser's first use.
    /// </summary>
    public Dictionary<string, string> ClassAnchors { get; init; } = new(StringComparer.Ordinal);

    /// <summary>
    /// Precomputed literal class-name prefixes used to import older literal
    /// anchors. Kept separate from <see cref="ClassAnchors"/> because anchors
    /// may contain wildcards and must not be escaped as literals.
    /// </summary>
    public Dictionary<string, string> ClassPrefixes { get; init; } = new(StringComparer.Ordinal);

    /// <summary>
    /// Precomputed exact terms that select more than one class at once. Paste
    /// composition only combines these verified groups; it never rescans the
    /// corpus or validates a heuristic candidate at runtime.
    /// </summary>
    public List<ClassGroupEntry> ClassGroups { get; init; } = [];

    /// <summary>
    /// Patterns with no safe verbatim line-local fragment in the global scope,
    /// with the reason. The class tables may still resolve them; the UI must
    /// not silently emit a broad fragment for these.
    /// </summary>
    public Dictionary<string, string> GlobalUnresolved { get; init; } = new(StringComparer.Ordinal);

    public Dictionary<string, Dictionary<string, string>> ByClassUnresolved { get; init; } =
        new(StringComparer.Ordinal);

    /// <summary>
    /// Picks whose min-value probe changes the compiled fragment. Only true
    /// entries are stored; a missing key falls back to the live probe.
    /// </summary>
    public MinCapableTable MinCapable { get; init; } = new();

    /// <summary>Stable table key: the plain mod id or the sorted variant ids.</summary>
    public static string MinCapableKey(string modId, IReadOnlyList<string>? variantIds)
    {
        if (variantIds is not { Count: > 0 }) return modId;
        return string.Join('\u0001', variantIds.OrderBy(x => x, StringComparer.Ordinal));
    }

    public bool TryGet(string? scope, string pattern, out string? fragment)
    {
        if (scope is null) return Global.TryGetValue(pattern, out fragment);
        if (ByClass.TryGetValue(scope, out var map)) return map.TryGetValue(pattern, out fragment);
        fragment = null;
        return false;
    }

    public string? UnresolvedReason(string? scope, string pattern)
    {
        if (scope is null) return GlobalUnresolved.GetValueOrDefault(pattern);
        return ByClassUnresolved.TryGetValue(scope, out var map) ? map.GetValueOrDefault(pattern) : null;
    }
}

/// <summary>Picks whose minimum changes the compiled fragment, by scope.</summary>
public sealed class MinCapableTable
{
    public HashSet<string> Global { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, HashSet<string>> ByClass { get; init; } =
        new(StringComparer.Ordinal);

    public bool TryGet(string? scope, string key, out bool capable)
    {
        var set = scope is null
            ? Global
            : ByClass.TryGetValue(scope, out var byClass) ? byClass : null;
        capable = set?.Contains(key) == true;
        return capable;
    }
}

/// <summary>One precomputed multi-class selector and the classes it matches.</summary>
public sealed class ClassGroupEntry
{
    public string Term { get; init; } = "";
    public List<string> Classes { get; init; } = [];
}

[JsonSerializable(typeof(FragmentTable))]
internal partial class FragmentTableJsonContext : JsonSerializerContext
{
}

/// <summary>Loads the embedded per-catalog fragment tables.</summary>
internal static class FragmentTables
{
    private static readonly Lazy<FragmentTable?> PoE2 =
        new(() => Load("PoeRegex.Core.catalogs.poe2.fragments.json"));

    public static FragmentTable? ForCurrentGame => PoE2.Value;

    private static FragmentTable? Load(string resourceName)
    {
        using var stream = typeof(FragmentTables).Assembly.GetManifestResourceStream(resourceName);
        if (stream is null) return null;
        try
        {
            return JsonSerializer.Deserialize(stream, FragmentTableJsonContext.Default.FragmentTable);
        }
        catch
        {
            return null;
        }
    }
}
